			let pointsCount = Math.round(rad * 3 / 2);
			let k_increment = 2 * Math.PI / pointsCount;
			let theta = 0.0;
			rad *= game_World.MOVER_SCALE;
			if(path.charAt(1) != "C") {
				k_increment = -k_increment;
			}
