class game_GhostMorphingParticles extends visual_Particles {
	constructor(world,numParticles) {
		super(numParticles);
		this.world = world;
		this.sprites = [];
		this.size = 0.6;
		this.sizeVar = 0.2;
		this.angle = math_random_Random_instance.fRand() * 360;
		this.angleVar = 15;
		this.rotateSpeedVar = 30;
		this.life = 0.8;
		this.lifeVar = 0.3;
		this.duration = 1.5;
		this.speed = 140;
		this.speedVar = 35;
	}
	startSystem(initialParticles) {
		super.startSystem(initialParticles);
	}
	initParticle(particle) {
		super.initParticle(particle);
		this.angle += 360 / this.totalParticles;
		let randomValue = math_random_Random_instance.fRandSym1();
		let fact = this.size + randomValue * this.sizeVar;
		let frame = F.withIdx(F.OBJ_GHOST_BUBBLES_DDDD,math_random_Random_instance.randRange(0,2));
		let size = Tex.ghost.atlas.getFrameByName(frame).sourceSize;
		particle.width = size.x * fact;
		particle.height = size.y * fact;
		particle.deltaAngle = this.rotateSpeed + this.rotateSpeedVar * math_random_Random_instance.fRandSym1();
		let sprite = new gfx_sprite_Sprite(null,Tex.ghost,frame);
		sprite.center();
		this.world.getLayer(5)._appendChild(sprite.spatial);
		this.sprites.push(sprite);
	}
	updateParticle(particle,index,dt) {
		particle.angle += particle.deltaAngle * dt;
		super.updateParticle(particle,index,dt);
	}
	removeParticle(index) {
		super.removeParticle(index);
		let sprite = this.sprites[index];
		this.sprites.splice(index,1);
		sprite.destroy();
	}
	draw() {
		super.draw();
		let _g = 0;
		let _g1 = this.particles.length;
		while(_g < _g1) {
			let i = _g++;
			let p = this.particles[i];
			let s = this.sprites[i];
			s.set_rotation(p.angle);
			s.set_scale(p.width / s._sourceSize.x * 0.4);
			s.set_x(p.pos.x);
			s.set_y(p.pos.y);
			s.set_alpha(p.alpha);
		}
	}
	update(dt) {
		super.update(dt);
		let _g = 0;
		let _g1 = this.particles.length;
		while(_g < _g1) {
			let p = this.particles[_g++];
			if(p.life > 0) {
				if(p.life < p.lifeStart * 0.7) {
					p.alpha = p.life / (p.lifeStart * 0.7);
				}
				p.dir.x *= 0.9;
				p.dir.y *= 0.9;
				p.width *= 1.015;
				p.height *= 1.015;
			}
		}
	}
}
